create table product_categories (id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null);
create table phones (id uuid primary key default gen_random_uuid(), category_id uuid references product_categories(id), slug text unique not null, name text not null, brand text not null, os text not null check (os in ('Android','iOS')), size text not null check (size in ('compact','large')), storage_gb int not null, is_active boolean default true);
create table phone_scores (phone_id uuid primary key references phones(id) on delete cascade, camera numeric check(camera between 0 and 100), battery numeric check(battery between 0 and 100), performance numeric check(performance between 0 and 100), video numeric check(video between 0 and 100), software numeric check(software between 0 and 100), display numeric check(display between 0 and 100), build numeric check(build between 0 and 100), value numeric check(value between 0 and 100));
create table merchants (id uuid primary key default gen_random_uuid(), name text not null, verified boolean default false, official boolean default false);
create table offers (id uuid primary key default gen_random_uuid(), phone_id uuid references phones(id), merchant_id uuid references merchants(id), price_cents int not null, condition text not null, warranty_months int not null, affiliate_deep_link text not null, updated_at timestamptz default now());
create table affiliate_clicks (id bigint generated always as identity primary key, phone_id uuid references phones(id), offer_id uuid references offers(id), profile_fingerprint text, created_at timestamptz default now());
create table recommendation_events (id bigint generated always as identity primary key, profile_vector jsonb not null, result_ids uuid[] not null, algorithm_version text not null, created_at timestamptz default now());
create table profile_clusters (id uuid primary key default gen_random_uuid(), centroid jsonb not null, sample_size int not null, updated_at timestamptz default now());
create table product_affinities (cluster_id uuid references profile_clusters(id), phone_id uuid references phones(id), affinity_boost numeric not null check(affinity_boost between -5 and 5), sample_size int not null, primary key(cluster_id,phone_id));
create view phone_catalog as select p.id,p.slug,p.name,p.brand,p.os,p.size,p.storage_gb as storage,p.is_active,s.*,o.price_cents/100.0 as price,json_build_object('merchant',m.name,'url',o.affiliate_deep_link,'warrantyMonths',o.warranty_months,'official',m.official,'updatedAt',o.updated_at) as offer from phones p join phone_scores s on s.phone_id=p.id join offers o on o.phone_id=p.id join merchants m on m.id=o.merchant_id;
